[[["Today is the farewell party for the English class.", "Hoje é a festa de despedida da turma de inglês."], ["The teacher is giving each student a certificate.", "A professora está dando um certificado a cada aluno."], ["Ana went up and made a short speech.", "Ana subiu e fez um discurso curto."], ["\"I'm proud of this class,\" she said.", "\"Tenho orgulho desta turma\", ela disse."], ["\"We had many lessons and made new friends.\"", "\"Tivemos muitas aulas e fizemos novos amigos.\""], ["\"Please keep in touch,\" the teacher said.", "\"Por favor, mantenham contato\", disse a professora."]], [["Ben, you look sad. Are you OK?", "Ben, você parece triste. Está bem?"], ["I'm fine, Ana. It is the last day of class, and I'm a little sad.", "Estou bem, Ana. É o último dia de aula, e estou um pouco triste."], ["Me too. I remember our first lesson. I was so nervous!", "Eu também. Lembro da nossa primeira aula. Eu estava tão nervosa!"], ["Yes! Now we can write a postcard or a story in English.", "Verdade! Agora podemos escrever um cartão-postal ou uma história em inglês."], ["True. The teacher is going to give each student a certificate, and then teach us a song.", "Verdade. A professora vai dar um certificado a cada aluno e depois nos ensinar uma música."], ["Nice! Did you write your speech?", "Legal! Você escreveu seu discurso?"], ["Yes, I did. It is short. I'm going to say thank you to everybody.", "Escrevi, sim. É curto. Vou agradecer a todo mundo."], ["That is a nice idea. I'm proud of you! Can we take a picture together?", "Boa ideia. Tenho orgulho de você! Podemos tirar uma foto juntos?"], ["Sure! After that, we can keep in touch. Here is my number.", "Claro! Depois disso, podemos manter contato. Aqui está meu número."], ["Yes, please! We can catch up at a reunion next year.", "Sim, por favor! Podemos pôr a conversa em dia num reencontro no ano que vem."]], ["/tʃ/ em speech e teach", "O /tʃ/ de speech, teach e each é o 'tch' de 'tchau'. No fim da palavra, a língua encosta no céu da boca e solta o ar de uma vez. Não acrescente 'i': é 'spiitch', não 'spiitchi'.", ["speech", "teach", "each"]], ["Ana ___ a short speech at the party.", "made", "make", "Ana fez um discurso curto na festa.", "Make é irregular: no passado vira made."], [["The teacher is giving each student a certificate.", "A professora está dando um certificado a cada aluno."], ["Yes, I did. It is short. I'm going to say thank you to everybody.", "Escrevi, sim. É curto. Vou agradecer a todo mundo."]], [{"t": "c", "q": "The teacher ___ each student a certificate now.", "o": ["is giving", "gave", "were giving"], "pt": "A professora está dando um certificado a cada aluno agora.", "why": "'Now' pede o present continuous: is giving."}, {"t": "l", "say": "Please keep in touch.", "o": ["Please keep in touch.", "Please keep in mind.", "Please sleep in touch."], "why": "Ouça touch (contato)."}, {"t": "b", "pt": "Tenho orgulho de você.", "w": ["I'm", "proud", "of", "you"]}, {"t": "b", "pt": "Nós vamos fazer um discurso.", "w": ["We", "are", "going", "to", "make", "a", "speech"]}]],
[[["Lia has a big dream for next year.", "Lia tem um grande sonho para o ano que vem."], ["She is going to learn more English.", "Ela vai aprender mais inglês."], ["Her goal is to travel and see many islands.", "A meta dela é viajar e conhecer muitas ilhas."], ["She wants a good job in the future.", "Ela quer um bom emprego no futuro."], ["Last year she was a student, and now she has a certificate.", "No ano passado ela era estudante, e agora tem um certificado."], ["Lia wants her dream to come true.", "Lia quer que seu sonho vire realidade."]], [["Noah, what is your plan for the future?", "Noah, qual é o seu plano para o futuro?"], ["I'm going to learn to drive next year. My goal is to buy a car.", "Vou aprender a dirigir no ano que vem. Minha meta é comprar um carro."], ["Cool! I'm going to travel to an island like the one on my old postcard.", "Legal! Vou viajar para uma ilha como a do meu cartão-postal antigo."], ["That sounds fun! Don't forget sunscreen. The weather is dry and sunny there.", "Parece divertido! Não esqueça o protetor solar. O clima lá é seco e ensolarado."], ["Good idea. I want a job with travel too. My dream is a career as a reporter.", "Boa ideia. Quero um emprego com viagens também. Meu sonho é uma carreira de repórter."], ["A reporter? You can write a headline for the newspaper!", "Repórter? Você pode escrever uma manchete para o jornal!"], ["Yes! And you? What career do you want?", "Sim! E você? Que carreira você quer?"], ["I want to be a plumber. I fixed a pipe last year, and I loved it.", "Quero ser encanador. Consertei um cano no ano passado e adorei."], ["That is a great plan! Please keep in touch, and we can catch up next year.", "Que ótimo plano! Mantenha contato, e podemos conversar de novo no ano que vem."], ["Yes, we can. I hope our dreams come true!", "Podemos, sim. Espero que nossos sonhos virem realidade!"]], ["/dr/ em dream e drive", "O /dr/ de dream, drive e dry começa com a língua já enrolada para o 'r'. Não coloque um 'i' entre o d e o r (não é 'dirim'), e o d sai quase como 'dj': 'dreem'.", ["dream", "drive", "dry"]], ["Lia ___ learn more English next year.", "is going to", "went to", "Lia vai aprender mais inglês no ano que vem.", "Para planos futuros use be going to + verbo base."], [["She is going to learn more English.", "Ela vai aprender mais inglês."], ["I'm going to learn to drive next year. My goal is to buy a car.", "Vou aprender a dirigir no ano que vem. Minha meta é comprar um carro."]], [{"t": "c", "q": "I hope our dreams ___ true.", "o": ["come", "comes", "coming"], "pt": "Espero que nossos sonhos virem realidade.", "why": "Dreams é plural, então o verbo fica sem -s: come true."}, {"t": "l", "say": "My goal is to travel.", "o": ["My goal is to travel.", "My goal is to trouble.", "My goal is to travel far."], "why": "Ouça travel (viajar), que termina logo depois."}, {"t": "b", "pt": "Eu vou aprender a dirigir.", "w": ["I'm", "going", "to", "learn", "to", "drive"]}, {"t": "b", "pt": "Eu consertei um cano no ano passado.", "w": ["I", "fixed", "a", "pipe", "last", "year"]}]]
