function plannedEnglishContent(){
  const row=englishLessonPlan()?englishA1Content[unit]:null;
  if(!row)return null;
  const lines=pairs=>pairs.map(([text,pt])=>({text,pt}));
  return {reading:lines(row[0]),dialogue:lines(row[1]),pronunciation:row[2],grammar:row[3],examples:row[4]?lines(row[4]):null,quiz:row[5]||null};
}
const englishA1GrammarPatterns=[
  /Can I have/i,/\ban\b/i,/^(?:go straight|yes\. cross|cross)/i,/\b(?:my|your)\b/i,/\bthere is\b/i,
  /would like/i,/\btwo (?:rolls|muffins|cookies)/i,/\bcan i\b/i,/\bat (?:seven|eight)\b/i,/one ticket/i,
  /\b(?:this|these) tickets?\b/i,/\blive (?:in|on|near)\b/i,/\bthere are\b/i,/\bis there\b/i,/next to|across from|by the/i,
  /before|after/i,/what time/i,/\b(?:am|is|are) (?:sending|typing|walking|going|waiting|doing|reading)\b/i,/\bwho is\b|this is/i,/\b(?:i am|this is|you are|we are)\b/i,
  /\bon friday\b/i,/table for/i,/\b(?:that|those)\b/i,/\bsome\b|glasses of water/i,/where can i sit/i,
  /do you like|i do\b/i,/do you have/i,/^(?:write|use|put|yes\. write)/i,/in (?:her|your|my) notebook|on the first page/i,/\b(?:we|they)\b/i,
  /^I (?:turn|check|look|use|start)\b/i,/\b(?:he|she) (?:uses|writes|studies|puts)\b/i,/do not|stay on/i,/small town|quiet street|white table/i,/want(?:s)? to/i,
  /what time does/i,/how long/i,/which/i,/must/i,/\b(?:first|second|third) row\b/i,
  /can we/i,/the next train/i,/\bhas\b|\bi have\b/i,/\bunder\b/i,/\bon the (?:first|second) floor\b/i,
  /please (?:ask|write)/i,/\b(?:am|are|is) (?:early|late|on time)\b/i,/\bcannot\b|\bcan i\b/i,/would you like to/i,/\b(?:and|but)\b/i
];
function plannedEnglishExamples(content){
  if(content.examples)return content.examples;
  const all=[...content.dialogue,...content.reading];
  const pattern=englishA1GrammarPatterns[unit];
  const matching=all.filter(line=>pattern.test(line.text));
  return [...new Map([...matching,...all].map(line=>[line.text,line])).values()].slice(0,2);
}

// Mini-quiz da lição (4 itens: lacuna, escuta, duas montagens) + revisão dos erros de lições anteriores.
function a1Missed(){try{return JSON.parse(localStorage.getItem('lpd-a1-missed')||'{}');}catch{return {};}}
function a1SaveMissed(m){try{localStorage.setItem('lpd-a1-missed',JSON.stringify(m));}catch{/* Sem armazenamento. */}}
function a1Shuffle(list,seed){const a=[...list];let x=seed*9301+49297;for(let i=a.length-1;i>0;i--){x=(x*9301+49297)%233280;const j=Math.floor(x/233280*(i+1));[a[i],a[j]]=[a[j],a[i]];}
  if(a.join(' ')===list.join(' ')&&a.length>1)a.push(a.shift());return a;}
function a1QuizItem(item,u,i,label){
  const id=u+':'+i, head='<div class="a1-q" data-a1q="'+id+'" data-t="'+item.t+'">'+(label?'<p class="meta">'+clean(label)+'</p>':'');
  const status='<p class="a1-status" role="status"></p></div>';
  if(item.t==='b'){
    const answer=item.w.join(' ');
    return head+'<p>Monte em inglês: <strong lang="pt-BR">'+clean(item.pt)+'</strong></p><p class="a1-built" lang="en" aria-live="polite"></p>'+
      '<div class="controls">'+a1Shuffle(item.w,u*7+i).map(w=>'<button type="button" data-a1-word="'+clean(w)+'">'+clean(w)+'</button>').join('')+'</div>'+
      '<div class="controls"><button type="button" data-a1-check="'+clean(answer)+'">Verificar</button><button type="button" data-a1-clear>Limpar</button></div>'+status;
  }
  const correct=item.t==='c'?item.o[0]:item.o[0];
  const opts=a1Shuffle(item.o,u*5+i);
  const body=item.t==='c'?'<p>Complete: '+nativeText(item.q)+'</p><p class="meta" lang="pt-BR">'+clean(item.pt)+'</p>':
    '<p>Ouça e escolha o que você ouviu.</p>'+lessonPlayButton(item.say);
  return head+body+'<div class="controls">'+opts.map(o=>'<button type="button" data-a1-opt="'+clean(o)+'" data-correct="'+clean(correct)+'" data-why="'+clean(item.why||'')+'">'+nativeText(o)+'</button>').join('')+'</div>'+status;
}
function renderA1Quiz(content){
  if(!content.quiz)return '';
  const missed=a1Missed(), review=Object.keys(missed).filter(k=>Number(k.split(':')[0])<unit).slice(0,2);
  const items=review.map(k=>{const [u,i]=k.split(':').map(Number);const row=englishA1Content[u]?.[5]?.[i];return row?a1QuizItem(row,u,i,'Revisão da lição '+(u+1)):'';}).join('')+
    content.quiz.map((item,i)=>a1QuizItem(item,unit,i)).join('');
  return '<section class="grammar-choice a1-quiz"><h4>Mini-quiz da lição</h4><p class="meta">Quatro itens: lacuna, escuta e duas frases para montar. O que você errar volta como revisão nas próximas lições.</p>'+items+'</section>';
}
function handleA1Quiz(event){
  const t=event.target;
  const opt=t.closest('[data-a1-opt]'),word=t.closest('[data-a1-word]'),check=t.closest('[data-a1-check]'),clear=t.closest('[data-a1-clear]');
  if(!(opt||word||check||clear))return false;
  const box=t.closest('.a1-q'),status=box.querySelector('.a1-status'),id=box.dataset.a1q;
  const finish=right=>{
    const m=a1Missed();
    if(right){delete m[id];status.dataset.feedback='correct';}else{m[id]=1;status.dataset.feedback='retry';}
    a1SaveMissed(m);
  };
  if(opt){
    const right=opt.dataset.a1Opt===opt.dataset.correct;
    status.textContent=right?'Certo. '+opt.dataset.why:'Ainda não. Ouça ou leia de novo e tente outra opção.';
    finish(right);
  }else if(word){
    const built=box.querySelector('.a1-built');built.textContent=(built.textContent?built.textContent+' ':'')+word.dataset.a1Word;word.disabled=true;
  }else if(clear){
    box.querySelector('.a1-built').textContent='';box.querySelectorAll('[data-a1-word]').forEach(b=>{b.disabled=false;});status.textContent='';
  }else{
    const right=box.querySelector('.a1-built').textContent.trim().toLowerCase()===check.dataset.a1Check.toLowerCase();
    status.textContent=right?'Certo. '+check.dataset.a1Check:'Ainda não. Confira a ordem das palavras e tente de novo.';
    finish(right);
  }
  return true;
}
function renderCompletedEnglishGrammar(plan,content,photo,used){
  const [question,correct,wrong,translation,reason]=content.grammar;
  const options=unit%2?[wrong,correct]:[correct,wrong];
  const choices='<section class="grammar-choice"><h4>Complete a frase</h4><div class="grammar-choice-case">'+nativeText(question,'p')+
    '<p class="meta" lang="pt-BR">'+clean(translation)+'</p><div class="controls">'+
    options.map(option=>'<button type="button" data-grammar-choice="'+clean(option)+'">'+nativeText(option)+'</button>').join('')+
    '</div><p class="grammar-choice-status" role="status" data-correct="'+clean(correct)+'" data-reason="'+clean(reason)+'" data-wrong="Ainda não. Releia os exemplos da regra e tente de novo."></p></div></section>'+renderA1Quiz(content);
  const examples=plannedEnglishExamples(content).map(({text,pt})=>[text,pt]);
  return '<article class="lesson-card">'+lessonPhotoFrame(photo,'a1-block-photo')+
    renderGrammarRule(plan.grammar,plan.goal,
    'Observe a posição da parte destacada no exercício. Use o contexto e a tradução para conferir a sua escolha.',
    examples,{},used,choices)+'</article>';
}
function buildCompletedEnglishLesson(plan,content){
  const [first,second]=plan.words;
  const vocabulary={
    word:first[0],expression:second[0],
    wordExample:plannedEnglishWordExample(first[0],content),
    expressionExample:plannedEnglishWordExample(second[0],content),
    meanings:[first[1],second[1]]
  };
  const focus=plannedEnglishExamples(content)[0];
  const sample=vocabulary.wordExample||focus;
  return {vocabulary,practiceContent:content,cardPhotos:new Set(plan.file?[plan.file]:[]),grammarTitle:plan.grammar,
    tasks:{word:vocabulary.word,phrase:vocabulary.expression,sentence:sample.text,translation:sample.pt}};
}
function plannedEnglishWordExample(term,content){
  const needle=term.replace(/[.…?!]+$/u,'');
  const example=[...content.reading,...content.dialogue].find(line=>Boolean(wordUseGap(line.text,needle)));
  const supplement=englishA1ExtraWordExamples[unit]?.[term];
  return example||(supplement?{text:supplement[0],pt:supplement[1]}:null);
}
function renderCompletedEnglishVocabulary(plan,content,photo){
  return '<section class="lesson-plan-card" aria-labelledby="planVocabularyTitle"><h3 id="planVocabularyTitle">Vocabulário da lição</h3>'+
    lessonPhotoFrame(photo,'a1-block-photo')+'<dl class="lesson-plan-words">'+
    plan.words.map(([term,meaning])=>{
      const example=plannedEnglishWordExample(term,content);
      return '<div><dt>'+nativeText(term)+lessonPlayButton(term,{compact:true})+'</dt><dd>'+clean(meaning)+
        (example?'<p>'+nativeText(example.text)+lessonPlayButton(example.text,{compact:true})+'</p><p lang="pt-BR">'+clean(example.pt)+'</p>':'')+'</dd></div>';
    }).join('')+'</dl></section>';
}
function renderCompletedEnglishScene(plan,content){
  const phrase=content.dialogue[content.dialogue.length-2];
  const reply=content.dialogue[content.dialogue.length-1];
  return '<section class="lesson-card" data-playback-block><h3>'+clean(plan.title)+'</h3><p>Ouça o último par de falas. Perceba qual informação a resposta confirma e diga que pergunta você faria em seguida.</p>'+
    sectionPlayButton('closing-exchange','Ouvir o final da conversa')+
    lessonLinesMarkup([phrase,reply],'dialogue')+'</section>';
}
function renderCompletedEnglishRoleplay(plan,content){
  const [prompt,answer]=content.grammar;
  const template=prompt.replace('___',answer);
  const secondTemplate=plannedEnglishExamples(content)[0].text.replace(/\p{L}+(?=[.?!]?$)/u,'…');
  const reply=content.dialogue[1];
  const writing=contextualRoleplayDraft();
  return '<section class="scene-roleplay" aria-labelledby="roleplayTitle"><h4 id="roleplayTitle">Faça uma versão sua</h4>'+
    '<p>Imagine que você está na cena “'+clean(plan.title)+'”. Use uma das ideias abaixo, troque um detalhe e confira se a sua fala ainda faz sentido.</p>'+
    '<div class="roleplay-writing"><p><strong>Molde 1</strong> '+nativeText(prompt)+'</p><p><strong>Molde 2</strong> '+nativeText(secondTemplate)+'</p>'+
    '<p class="meta">Dica: mantenha o padrão de '+clean(plan.grammar)+' e mude uma pessoa, um objeto, um local ou um horário que faça sentido.</p>'+
    '<label for="roleplayDraft">Escreva sua fala</label>'+writing+
    '<details class="roleplay-model"><summary>Ouvir exemplos de referência</summary>'+nativeText(template,'p')+lessonPlayButton(template,{compact:true})+
    nativeText(reply.text,'p')+lessonPlayButton(reply.text,{compact:true})+'<p lang="pt-BR">'+clean(reply.pt)+'</p></details></div></section>';
}
function contextualRoleplayDraft(){
  return '<textarea id="roleplayDraft" rows="3" lang="en-US" dir="auto">'+clean(roleplayDrafts.get(lessonHash(unit))||'')+'</textarea>';
}

const englishA1MiniStories={
  9:["A água não está gelada",`Ivy and Tom are at a restaurant.~A Ivy e o Tom estão num restaurante.|It is a hot day, and they are thirsty.~É um dia quente, e eles estão com sede.|Ivy: “Can I have some water, please?”~Ivy: “Posso pedir um pouco de água, por favor?”|Tom: “And can I have some juice, please?”~Tom: “E posso pedir um pouco de suco, por favor?”|A glass of water is on the table, but the water is not cold.~Um copo de água está na mesa, mas a água não está gelada.|Ivy: “Excuse me. This water is not cold.”~Ivy: “Com licença. Esta água não está gelada.”|The server: “Sorry! Would you like some ice?”~O garçom: “Desculpe! Você gostaria de um pouco de gelo?”|Ivy: “Yes, I would like some ice, please.”~Ivy: “Sim, eu gostaria de um pouco de gelo, por favor.”|Now the water is cold, and the juice is cold too.~Agora a água está gelada, e o suco também.|Ivy and Tom are happy.~A Ivy e o Tom estão felizes.`],
  19:["O cachorro na cafeteria",`Ana and I are in a small seaside town.~Ana e eu estamos numa cidade litorânea pequena.|We are hungry, so we sit at a café.~Estamos com fome, então sentamos numa cafeteria.|I look in my bag, but I have no money.~Olho na minha bolsa, mas não tenho dinheiro.|I am sad, and Ana is sad too.~Estou triste, e a Ana também está.|There is a big white dog under the table.~Há um cachorro grande e branco debaixo da mesa.|The dog is happy to see us.~O cachorro está feliz em nos ver.|Then I see a small blue bag by the dog.~Então vejo uma bolsa azul pequena perto do cachorro.|It is my bag, and my money is in it!~É a minha bolsa, e meu dinheiro está nela!|We are so happy, and we eat a big lunch.~Ficamos muito felizes e comemos um grande almoço.|We say thank you to the white dog, and it is happy too.~Dizemos obrigado ao cachorro branco, e ele também está feliz.`],
  29:["A toalha vermelha",`Rita and Bo go to the beach.~Rita e Bo vão à praia.|The sand is hot, and the sun is big.~A areia está quente, e o sol está forte.|They have a red towel.~Eles têm uma toalha vermelha.|They put the towel on the sand.~Eles colocam a toalha na areia.|Then they swim in the cold water.~Depois eles nadam na água fria.|Rita and Bo come back to the towel.~Rita e Bo voltam para a toalha.|The red towel is not on the sand!~A toalha vermelha não está na areia!|A small dog is near the water.~Um cachorro pequeno está perto da água.|The red towel is on the dog!~A toalha vermelha está no cachorro!|Rita and Bo are happy, and they take the towel.~Rita e Bo estão felizes, e pegam a toalha.`],
  39:["A reserva no nome do pai",`Lia and her father arrive at a hotel at night.~Lia e o pai dela chegam a um hotel à noite.|They are tired, and they want a room.~Eles estão cansados e querem um quarto.|Lia goes to the front desk.~Lia vai até a recepção.|The clerk asks, “What name is the reservation under?”~O recepcionista pergunta: “Em que nome está a reserva?”|Lia says, “It is under my name.”~Lia diz: “Está no meu nome.”|The clerk looks at the computer, but she cannot find it.~A recepcionista olha o computador, mas não consegue achar.|Lia is sad.~Lia fica triste.|Her father says, “Try my name, Tom Rossi.”~O pai dela diz: “Tente o meu nome, Tom Rossi.”|The clerk looks again and finds it. It is under her father's name!~A recepcionista olha de novo e acha. Está no nome do pai dela!|Now they are happy, and they take the key to their room.~Agora eles estão felizes e levam a chave para o quarto.`],
  49:["Uma surpresa na cafeteria",`Tina and Lou sit in a coffee shop.~Tina e Lou sentam em uma cafeteria.|It is five o'clock, and Lou is tired.~São cinco horas, e o Lou está cansado.|Tina has a cup of coffee, and Lou has tea.~A Tina tem uma xícara de café, e o Lou tem um chá.|Lou wants to go home, but Tina wants to stay a little longer.~O Lou quer ir para casa, mas a Tina quer ficar mais um pouco.|A woman at the next table looks at them.~Uma mulher na mesa ao lado olha para eles.|She says hello, and Lou looks at her.~Ela diz oi, e o Lou olha para ela.|It is Rosa, a friend from school!~É a Rosa, uma amiga da escola!|Lou is not tired now.~O Lou não está mais cansado.|The three friends talk and drink tea.~Os três amigos conversam e tomam chá.|Then they go home, and Lou sleeps well.~Depois eles vão para casa, e o Lou dorme bem.`],
  59:["A lista perdida",`Ana has a big bag, and Tom has a small basket.~Ana tem uma bolsa grande, e Tom tem uma cesta pequena.|They have a list: tomatoes, carrots, and grapes.~Eles têm uma lista: tomates, cenouras e uvas.|At the first stall, Ana sees fresh fruit.~Na primeira barraca, Ana vê fruta fresca.|Tom says, "Look! I see my bananas!"~Tom diz: "Olhe! Estou vendo as minhas bananas!"|He puts the bananas in his basket.~Ele põe as bananas na cesta dele.|Now Ana looks in her bag, but the list is not there!~Agora a Ana olha na bolsa, mas a lista não está lá!|Tom says, "Do you have your phone?"~Tom diz: "Você está com o celular?"|Ana has a photo of the list on her phone.~Ana tem uma foto da lista no celular.|They buy the tomatoes, the carrots, and the grapes.~Eles compram os tomates, as cenouras e as uvas.|Ana smiles and says, "Thank you, Tom, you are a good brother!"~Ana sorri e diz: "Obrigada, Tom, você é um bom irmão!"`],
  69:["Formigas no piquenique",`Lia has a picnic in the park with her dog, Max.~Lia faz um piquenique no parque com o cachorro dela, o Max.|She puts a blanket on the grass.~Ela coloca um cobertor na grama.|The basket has sandwiches, lemonade, and a ball.~A cesta tem sanduíches, limonada e uma bolinha.|Lia sits in the sun, and Max looks at the sandwiches.~Lia senta no sol, e Max olha para os sanduíches.|Suddenly, many ants walk on the blanket!~De repente, muitas formigas andam no cobertor!|Lia says, "Oh no! Let's move!"~Lia diz: "Ah, não! Vamos sair daqui!"|They take the basket and go under a big tree.~Eles pegam a cesta e vão para baixo de uma árvore grande.|Max runs and plays with the ball in the shade.~Max corre e brinca com a bolinha na sombra.|There are no ants under the tree.~Não há formigas debaixo da árvore.|Lia smiles and says, "Let's come back next Saturday!"~Lia sorri e diz: "Vamos voltar no próximo sábado!"`],
  79:["A semente mágica",`Ana has a small garden behind the garage.~A Ana tem um jardim pequeno atrás da garagem.|One day, she finds a strange seed on the wall.~Um dia, ela acha uma semente estranha na parede.|She puts the seed in the soil with a shovel.~Ela coloca a semente na terra com uma pá.|She gives it water, but nothing happens.~Ela dá água para ela, mas nada acontece.|The next day, there is still nothing.~No dia seguinte, ainda não tem nada.|Ana is sad, but she waits.~Ana fica triste, mas espera.|Then a small green plant comes up!~Então uma plantinha verde nasce!|It grows and grows, and soon it has lots of flowers.~Ela cresce e cresce, e logo tem muitas flores.|A bee and a butterfly come, and her rabbit jumps with joy.~Uma abelha e uma borboleta chegam, e o coelho dela pula de alegria.|It is a magic seed, and now Ana has the best garden in town!~É uma semente mágica, e agora a Ana tem o melhor jardim da cidade!`],
  89:["O caixa mistério",`Lia is at the bank with her colleague Ben.~A Lia está no banco com o colega Ben.|She needs cash for the soccer team.~Ela precisa de dinheiro para o time de futebol.|First, she puts her card in the ATM.~Primeiro, ela coloca o cartão no caixa.|Then she types her pin, but the screen says no.~Depois ela digita a senha, mas o visor diz não.|"Oh no, it is the wrong pin!" says Lia.~"Ai não, é a senha errada!", diz a Lia.|Ben says, "Stop and think about your pin."~O Ben diz: "Pare e pense na sua senha."|Lia thinks, and then she smiles.~A Lia pensa, e então sorri.|She types the new pin, and the machine says okay.~Ela digita a senha nova, e a máquina diz que está tudo certo.|Now the ATM gives her cash, and there is a coin in the slot too!~Agora o caixa dá o dinheiro, e tem uma moeda na abertura também!|Lia is happy, and she gets a drink for the whole team.~A Lia está feliz e compra uma bebida para o time inteiro.`],
  99:["A cama grande",`Tom and Ana carry a big bed to the stairs.~O Tom e a Ana carregam uma cama grande até a escada.|The bed is too big, and it does not go up.~A cama é grande demais e não sobe.|Ana says, "Let's try again."~A Ana diz: "Vamos tentar de novo."|They turn the bed, but it still does not go.~Eles viram a cama, mas ela continua não passando.|Tom looks at the bed and sees four legs.~O Tom olha a cama e vê quatro pés.|"I can take the legs off," he says.~"Eu consigo tirar os pés", ele diz.|Ana gets a tool from the truck.~A Ana pega uma ferramenta no caminhão.|Tom works fast, and the legs come off.~O Tom trabalha rápido, e os pés saem.|Now the bed goes upstairs easily.~Agora a cama sobe com facilidade.|In the bedroom, they put the legs on again, and Ana smiles.~No quarto, eles recolocam os pés, e a Ana sorri.`],
  109:["O martelo novo",`Tom is a worker on a new building.~Tom é operário num prédio novo.|He has a hammer, a ladder, and a hard hat.~Ele tem um martelo, uma escada de mão e um capacete.|At twelve o'clock, Tom wants his lunch.~Ao meio-dia, Tom quer almoçar.|He looks for his hammer, but it is not on the ladder.~Ele procura o martelo, mas ele não está na escada.|Tom is sad, because the hammer is new.~Tom está triste, porque o martelo é novo.|He asks his friends, "Where is my hammer?"~Ele pergunta aos amigos: "Onde está o meu martelo?"|They look under the bricks, but there is no hammer.~Eles olham embaixo dos tijolos, mas não há martelo.|Then a boy near the fence says, "Is this your hammer?"~Então um menino perto da cerca diz: "Este é o seu martelo?"|The boy has the hammer, and it has Tom's name on it.~O menino está com o martelo, e ele tem o nome do Tom.|Tom is happy, and he says, "Thank you! I am not sad now."~Tom fica feliz e diz: "Obrigado! Agora não estou triste."`],
  119:["O fantasma na porta",`Last Halloween, Ben played with his cousin Lia.~No Halloween passado, Ben brincou com a prima Lia.|They walked to a big, old house.~Eles andaram até uma casa grande e velha.|The house was dark, and a pumpkin was on the door.~A casa estava escura, e uma abóbora estava na porta.|Ben knocked, but nobody answered.~Ben bateu, mas ninguém respondeu.|Suddenly a ghost opened the door!~De repente, um fantasma abriu a porta!|Ben jumped, and Lia laughed.~Ben pulou, e Lia riu.|The ghost wasn't a ghost. It was Mr. Lopez with a white sheet.~O fantasma não era um fantasma. Era o Sr. Lopez com um lençol branco.|He wanted a joke for the kids.~Ele queria fazer uma brincadeira com as crianças.|He filled their bags with candy.~Ele encheu as sacolas deles de doces.|Ben and Lia thanked him, and they walked home happy.~Ben e Lia agradeceram a ele e voltaram para casa felizes.`],
  129:["O sonho do Tom",`Tom had a big dream. He wanted to be a singer.~Tom tinha um grande sonho. Ele queria ser cantor.|But Tom was shy, and he didn't sing for other people.~Mas Tom era tímido e não cantava para outras pessoas.|One day, his sister Mia took a video of him in the kitchen.~Um dia, a irmã dele, Mia, gravou um vídeo dele na cozinha.|She didn't tell him.~Ela não contou a ele.|Mia showed the video to a reporter from the radio.~Mia mostrou o vídeo a um repórter da rádio.|The reporter loved the song!~O repórter adorou a música!|The next day, Tom saw his name in the newspaper.~No dia seguinte, Tom viu o nome dele no jornal.|The headline said, "A new singer in our town!"~A manchete dizia: "Um novo cantor na nossa cidade!"|Tom was nervous, but he went to the radio show.~Tom estava nervoso, mas foi ao programa de rádio.|Now Tom is going to sing at a big concert, and his dream came true.~Agora Tom vai cantar num grande show, e o sonho dele virou realidade.`]
};
function renderCompletedEnglishStory(){
  const story=englishLessonPlan()?englishA1MiniStories[unit]:null;
  if(!story)return '';
  const [title,raw]=story;
  const lines=raw.split('|').map(line=>{const [text,pt]=line.split('~');return {text,pt};});
  return '<section class="lesson-card" data-playback-block><h3>'+clean(title)+'</h3><p>Conte com uma frase o que mudou entre o início e o fim. Ouça primeiro e depois volte ao texto em português.</p>'+
    sectionPlayButton('a1-story','Ouvir a mini-história')+lessonLinesMarkup(lines,'story')+'</section>';
}

